  push!(__eqs, u_air[3] ~ getindex(getproperty(mount, :v), 3) + getindex(getproperty(mount, :w), 1) * r_hub[2] - getindex(getproperty(mount, :w), 2) * r_hub[1] - (getindex(getproperty(mount, :R), 1, 3) * wind_ned[1] + getindex(getproperty(mount, :R), 2, 3) * wind_ned[2] + getindex(getproperty(mount, :R), 3, 3) * wind_ned[3]))
  push!(__eqs, V_c ~ -u_air[3])
  push!(__eqs, V_xy2 ~ u_air[1] ^ 2 + u_air[2] ^ 2)
  push!(__eqs, OR ~ Omega * Rp)
  push!(__eqs, den ~ OR ^ 2 + V_xy2 / mu_max ^ 2 + 0.000001)
  push!(__eqs, T_per_Omega ~ rho * A * (sigma * a_lift / 2) * Rp * (theta75 / 3 * OR + cf * V_xy2 * OR / den - (V_c + v_i) / 2))
  push!(__eqs, T ~ Omega * T_per_Omega)
  push!(__eqs, V_T ~ sqrt(V_xy2 + (V_c + v_i) ^ 2 + v_eps ^ 2))
  push!(__eqs, m_a * ModelingToolkit.D_nounits(v_i) ~ T - 2 * rho * A * v_i * V_T)
  push!(__eqs, Q ~ (V_c + v_i) * T_per_Omega + rho * A * Rp * (sigma * Cd0 / 8) * OR * abs(OR) * (1 + 4.65 * V_xy2 / den))
  push!(__eqs, P_aero ~ Q * Omega)
  push!(__eqs, F_aero[1] ~ -k_H * Omega * u_air[1])
  push!(__eqs, F_aero[2] ~ -k_H * Omega * u_air[2])
  push!(__eqs, F_aero[3] ~ -T)
  push!(__eqs, h_z ~ J * spin * Omega)
  push!(__eqs, mount.f ~ -F_aero)
  push!(__eqs, getindex(getproperty(mount, :tau), 1) ~ getindex(getproperty(mount, :w), 2) * h_z - (r_hub[2] * F_aero[3] - r_hub[3] * F_aero[2]))
  push!(__eqs, getindex(getproperty(mount, :tau), 2) ~ -getindex(getproperty(mount, :w), 1) * h_z - (r_hub[3] * F_aero[1] - r_hub[1] * F_aero[3]))
  push!(__eqs, getindex(getproperty(mount, :tau), 3) ~ -support.tau * spin - (r_hub[1] * F_aero[2] - r_hub[2] * F_aero[1]))

  # Return completely constructed System
  return System(__eqs, ModelingToolkit.t_nounits, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export Propeller
